<?php
require_once dirname(__DIR__).'/config.php';
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
function db(){static $db=null;if($db)return $db;try{$db=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $db;}catch(Throwable $e){http_response_code(503);exit('<h2>Banco não conectado</h2><p>Importe database/instalar.sql no phpMyAdmin e confira config.php.</p>');}}
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function url($path=''){return '/support-desk/'.ltrim($path,'/');}
function go($path){header('Location: '.url($path));exit;}
function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(20));return $_SESSION['csrf'];}
function csrf(){if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals(token(),(string)($_POST['csrf']??''))){http_response_code(419);exit('Sessão expirada. Atualize a página.');}}
function me(){if(empty($_SESSION['uid']))return null;$s=db()->prepare('SELECT id,name,email,role,active_plan,plan_expires_at,is_blocked,avatar_file FROM users WHERE id=?');$s->execute([$_SESSION['uid']]);return $s->fetch()?:null;}
function has_subscription($u){return $u && !empty($u['active_plan']) && !empty($u['plan_expires_at']) && strtotime($u['plan_expires_at'])>time();}
function require_user($admin=false){$u=me();if(!$u)go('auth/login.php');if(!empty($u['is_blocked'])){unset($_SESSION['uid']);go('auth/login.php');}if($admin&&$u['role']!=='admin')go('user/dashboard.php');if(!$admin&&$u['role']==='admin')go('admin/dashboard.php');return $u;}
function require_logged_in(){ $u=me(); if(!$u)go('auth/login.php'); if(!empty($u['is_blocked'])){unset($_SESSION['uid']);go('auth/login.php');} return $u; }
function require_subscriber(){ $u=require_user(); if(!has_subscription($u)){notify('Para acessar chamados, escolha e ative um plano demonstrativo.');go('plans.php');}return $u;}
function settings(){static $v=null;if($v!==null)return $v;$v=['site_name'=>'SupportDesk','hero_title'=>'Suporte eficiente. Tudo sob controle.','hero_text'=>'Central profissional de chamados com atendimento organizado e acompanhamento transparente.','accent'=>'#1677ff','announcement'=>''];try{foreach(db()->query('SELECT setting_key,setting_value FROM site_settings') as $row){$v[$row['setting_key']]=$row['setting_value'];}}catch(Throwable $e){}return $v;}

function notify($txt){$_SESSION['notice']=$txt;}
function flash(){if(!empty($_SESSION['notice'])){$x=$_SESSION['notice'];unset($_SESSION['notice']);echo '<div class="notice">'.h($x).'</div>';}}
function plans(){return [
 'essencial'=>['name'=>'Essencial','price'=>29.90,'info'=>'Para uso pessoal e dúvidas pontuais','limit'=>8,'response'=>'Até 72 horas úteis','features'=>['8 novos chamados por mês','Suporte de software e dúvidas','Histórico de conversas']],
 'profissional'=>['name'=>'Profissional','price'=>59.90,'info'=>'Para quem precisa de atendimento frequente','limit'=>12,'response'=>'Até 24 horas úteis','features'=>['12 novos chamados por mês','Software, hardware e redes','Prioridade no atendimento','Histórico completo']],
 'empresarial'=>['name'=>'Empresarial','price'=>99.90,'info'=>'Para operações e equipes','limit'=>0,'response'=>'Fila preferencial (meta de 8 horas úteis)','features'=>['Chamados ilimitados','Software, hardware, redes e segurança','Fila preferencial','Histórico e visão ampliada']]
];}
function plan_data($u){foreach(plans() as $p)if(strcasecmp($p['name'],(string)($u['active_plan']??''))===0)return $p;return null;}
function notification_create($userId,$title,$body,$link){$s=db()->prepare('INSERT INTO notifications(user_id,title,body,link_url) VALUES(?,?,?,?)');$s->execute([$userId,$title,$body,$link]);}
function notify_admins($title,$body,$link){$ids=db()->query("SELECT id FROM users WHERE role='admin' AND is_blocked=0")->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $id)notification_create($id,$title,$body,$link);}
function unread_count($uid){$s=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL');$s->execute([$uid]);return (int)$s->fetchColumn();}
function recent_notifications($uid,$limit=6){$s=db()->prepare('SELECT id,title,body,link_url,created_at,read_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT '.(int)$limit);$s->execute([$uid]);return $s->fetchAll();}

function status_badge($status){$key=mb_strtolower(trim((string)$status),'UTF-8');$map=['aberto'=>'open','em andamento'=>'progress','resolvido'=>'solved','fechado'=>'closed'];$class=$map[$key]??'neutral';return '<span class="ticket-status status-'.$class.'"><span class="status-dot" aria-hidden="true"></span>'.h($status).'</span>';}
function money($n){return 'R$ '.number_format((float)$n,2,',','.');}
function site_css(){
  $file=dirname(__DIR__).'/assets/css/style.css';
  return is_readable($file) ? file_get_contents($file) : '';
}
function layout_start($title,$u=null){
 $u=$u??me();$admin=$u&&$u['role']==='admin';$st=settings();$accent=preg_match('/^#[0-9a-fA-F]{6}$/',$st['accent'])?$st['accent']:'#1677ff';
 $popupNotices=$u?recent_notifications($u['id'],6):[];$popupUnread=$u?unread_count($u['id']):0;
 echo '<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070e1b"><title>'.h($title).' | '.h($st['site_name']).'</title><style>'.site_css().'</style><link rel="stylesheet" href="'.url('assets/css/pro.css').'"><link rel="stylesheet" href="'.url('assets/css/polish.css?v=6').'"><link rel="stylesheet" href="'.url('assets/css/v7.css?v=7').'"><link rel="stylesheet" href="'.url('assets/css/v8.css?v=8').'"><link rel="stylesheet" href="'.url('assets/css/v9.css?v=9').'"><link rel="stylesheet" href="'.url('assets/css/v10.css?v=10.2').'"><link rel="stylesheet" href="'.url('assets/css/v11.css?v=11.1').'"><link rel="stylesheet" href="'.url('assets/css/v12.css?v=12.1').'"><link rel="stylesheet" href="'.url('assets/css/v13.css?v=13.0').'"><link rel="stylesheet" href="'.url('assets/css/v14.css?v=14.1').'"><link rel="stylesheet" href="'.url('assets/css/v16.css?v=16').'"><link rel="stylesheet" href="'.url('assets/css/v18.css?v=18').'"><link rel="stylesheet" href="'.url('assets/css/v19.css?v=19.1').'"><link rel="stylesheet" href="'.url('assets/css/v22.css?v=22').'"><style>:root{--accent:'.h($accent).'}</style><script>try{document.documentElement.dataset.theme=localStorage.getItem("sd-theme")||"dark"}catch(e){document.documentElement.dataset.theme="dark"}</script></head><body><header class="top top-v14"><div class="nav nav-v14"><a class="brand brand-v14" href="'.url().'"><img src="'.url('assets/img/logo-icon.png').'" alt="SupportDesk" class="brand-logo"><span class="brand-name">'.h($st['site_name']).'</span></a><nav class="main-navigation"><a href="'.url('index.php').'">Início</a><a href="'.url('servicos.php').'">Serviços</a><a href="'.url('como-funciona.php').'">Como funciona</a><a href="'.url('sobre.php').'">Sobre nós</a><a href="'.url('faq.php').'">FAQ</a><a href="'.url('diagnostico.php').'">Diagnóstico</a><a href="'.url('plans.php').'">Planos</a>';
 if($u){
   if($admin){
     echo '<a class="navpill" href="'.url('admin/dashboard.php').'">Painel de controle</a>';
   }else{
     echo '<a href="'.url('user/dashboard.php').'">Meu painel</a>';
   }
   echo '<button type="button" class="notification-link notification-trigger" id="notificationTrigger" aria-haspopup="dialog" aria-controls="notifPopover" aria-expanded="false" aria-label="Abrir notificações">🔔 <span class="notification-label">Avisos</span> <span class="notification-counter">'.$popupUnread.'</span></button>';
   echo '<a class="profile-nav-link" href="'.url('profile.php').'">'.(!empty($u['avatar_file'])?'<img src="'.url('uploads/avatars/'.$u['avatar_file']).'" alt="" class="profile-nav-avatar">':'<span class="profile-nav-fallback">'.h(mb_strtoupper(mb_substr($u['name'],0,1))).'</span>').'<span>Meu perfil</span></a><a class="navpill" href="'.url('auth/logout.php').'">Sair</a>';
 }else echo '<a class="navpill" href="'.url('auth/login.php').'">Entrar</a>';
 echo '<button type="button" class="theme-toggle" id="themeToggle" aria-label="Alternar tema">◐ <span id="themeLabel">Tema</span></button></nav></div></header>';
 if($u){
   echo '<div class="notif-popover" id="notifPopover" role="dialog" aria-label="Notificações recentes" hidden><div class="notif-popover-head"><div><strong>Notificações</strong><small>'.$popupUnread.' não lidas</small></div><button type="button" class="notif-close" id="notifClose">×</button></div><div class="notif-popover-list">';
   if($popupNotices){foreach($popupNotices as $pn){echo '<a class="notif-popover-item'.($pn['read_at']?'':' is-new').'" href="'.url('notification-open.php?id='.(int)$pn['id']).'"><strong>'.h($pn['title']).'</strong><span>'.h(mb_strimwidth($pn['body'],0,100,'...')).'</span><small>'.date('d/m H:i',strtotime($pn['created_at'])).'</small></a>';}}
   else echo '<div class="notif-empty">Nenhuma notificação por enquanto.</div>';
   echo '</div><div class="notif-popover-foot"><a class="btn secondary block" href="'.url('notifications.php').'">Abrir central de notificações</a></div></div><div class="notif-backdrop" id="notifBackdrop" hidden></div>';
 }
 echo '<main class="container">';if(!empty($st['announcement']))echo '<div class="site-announcement">'.h($st['announcement']).'</div>';flash();
}

function layout_end(){echo '</main><footer class="site-footer"><div class="footer-shell"><div class="footer-brand"><img src="'.url('assets/img/logo-full.png').'" alt="SupportDesk Assistência Técnica" class="footer-logo"><p>Especialistas em assistência técnica e soluções de TI para pessoas, profissionais e empresas.</p><div class="footer-social"><span>Software</span><span>Hardware</span><span>Redes</span><span>Segurança</span></div></div><div class="footer-links"><div><h4>Navegação</h4><a href="'.url('index.php').'">Início</a><a href="'.url('servicos.php').'">Serviços</a><a href="'.url('plans.php').'">Planos</a><a href="'.url('sobre.php').'">Sobre nós</a></div><div><h4>Atendimento</h4><a href="'.url('como-funciona.php').'">Como funciona</a><a href="'.url('faq.php').'">Dúvidas frequentes</a><a href="'.url('diagnostico.php').'">Diagnóstico</a><a href="'.url('auth/login.php').'">Área do cliente</a></div><div><h4>Contato</h4><span>Suporte técnico digital</span><span>Atendimento organizado</span><span>Chamados e assinaturas</span><span>Projeto acadêmico demonstrativo</span></div></div></div><div class="footer-bottom"><span>© '.date('Y').' SupportDesk · Assistência Técnica</span><span>Desenvolvido para demonstração acadêmica com visual profissional.</span></div></footer><script>(function(){function update(){var d=document.documentElement.dataset.theme;var l=document.getElementById("themeLabel");if(l)l.textContent=d==="dark"?"Claro":"Escuro";}var b=document.getElementById("themeToggle");if(b)b.addEventListener("click",function(){var theme=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=theme;try{localStorage.setItem("sd-theme",theme)}catch(e){}update()});update();var t=document.getElementById("notificationTrigger"),p=document.getElementById("notifPopover"),c=document.getElementById("notifClose"),bd=document.getElementById("notifBackdrop");function closeP(){if(p){p.hidden=true;p.classList.remove("open");}if(bd)bd.hidden=true;if(t)t.setAttribute("aria-expanded","false");}function openP(){if(p){p.hidden=false;setTimeout(function(){p.classList.add("open")},10);}if(bd)bd.hidden=false;if(t)t.setAttribute("aria-expanded","true");}if(t&&p){t.addEventListener("click",function(e){e.preventDefault();p.hidden?openP():closeP();});document.addEventListener("keydown",function(e){if(e.key==="Escape")closeP();});document.addEventListener("click",function(e){if(!p.hidden&&!p.contains(e.target)&&!t.contains(e.target))closeP();});}if(c)c.addEventListener("click",closeP);if(bd)bd.addEventListener("click",closeP);var toast=document.querySelector(".notice");if(toast){setTimeout(function(){toast.classList.add("show")},60);setTimeout(function(){toast.classList.remove("show")},4200);}
var quickType=document.getElementById("quickIssueType");if(quickType){var info=document.getElementById("quickIssueInfo");var subject=document.getElementById("quickSubject");var category=document.getElementById("quickCategory");var hints={Software:["Erro de aplicativo","Software","Meu programa apresenta erro ao abrir e preciso de ajuda para corrigir o problema."],Hardware:["Equipamento com falha","Hardware","Meu equipamento está apresentando falhas de funcionamento e preciso de suporte técnico."],Redes:["Problema de conectividade","Redes","Estou com problema de internet, Wi-Fi ou rede local e preciso de ajuda."],Segurança:["Suspeita de segurança","Segurança","Identifiquei um possível risco de segurança e preciso de orientação."]};function syncQuick(){var v=quickType.value;if(!hints[v])return;subject.value=hints[v][0];category.value=hints[v][1];info.value=hints[v][2];}quickType.addEventListener("change",syncQuick);syncQuick();}
})();</script></body></html>';} 
function fld($name,$label,$type='text',$value='',$required=true){echo '<label class="field"><span>'.h($label).'</span><input type="'.h($type).'" name="'.h($name).'" value="'.h($value).'" '.($required?'required':'').'></label>';}
